 useEffect(()=>{if(!menu)return;const previous=document.activeElement,oldOverflow=document.body.style.overflow;document.body.style.overflow='hidden';const nav=document.getElementById('workspace-navigation');nav?.querySelector('.workspace-close')?.focus();const keydown=e=>{if(e.key==='Escape'){setMenu(false);return;}if(e.key==='Tab'){const items=[...nav.querySelectorAll('a,button')].filter(el=>!el.disabled&&el.getClientRects().length);if(e.shiftKey&&document.activeElement===items[0]){e.preventDefault();items.at(-1)?.focus();}else if(!e.shiftKey&&document.activeElement===items.at(-1)){e.preventDefault();items[0]?.focus();}}};document.addEventListener('keydown',keydown);return()=>{document.body.style.overflow=oldOverflow;document.removeEventListener('keydown',keydown);previous?.focus();};},[menu]);
