 const pending=data.orders.filter(o=>o.payment_status==='submitted'),processing=data.orders.filter(o=>o.status==='processing'),refunds=data.refunds.filter(r=>r.status==='requested'),low=data.products.filter(p=>p.active&&p.stock<10);
