     <div className="hero-chart-head"><h3>{metric==='daily'?'Sales trend':'Customer activity by hour'}</h3><div className="segmented small"><button className={metric==='daily'?'selected':''} onClick={()=>{setMetric('daily');setSelected(null);}}>Paid sales</button><button className={metric==='hours'?'selected':''} onClick={()=>{setMetric('hours');setSelected(null);}}>Active hours</button></div></div>
     {series.some(s=>s.value>0)?<><TrendChart series={series} metric={metric} selected={selected} onSelect={setSelected} label={metric==='daily'?'Recorded paid sales by day':'Signed-in events by hour'}/><div className="chart-readout" aria-live="polite">{selected?<><b>{selected.name}</b> {metric==='daily'?money(selected.value):selected.value+' signed-in customer events'}</>:'Select a bar for details.'}</div></>:<Empty title="No recorded activity in this period">Activity appears after customers use the live store and payments are verified.</Empty>}
