function ProductsPage(){
 const{data,repository}=useApp(),task=useTask(),[q,setQ]=useState(''),[category,setCategory]=useState(''),[editing,setEditing]=useState(null),[archive,setArchive]=useState(null),[page,setPage]=useState(1);const categories=[...new Set(data.products.map(p=>p.category))].sort(),rows=data.products.filter(p=>(!category||p.category===category)&&(!q||(p.name+' '+p.sku+' '+p.brand).toLowerCase().includes(q.toLowerCase()))),visible=rows.slice((page-1)*15,page*15);
 return <><SectionTitle eyebrow="YOUR STORE CATALOGUE" title="Products" action={<Button onClick={()=>setEditing({new:true})}><Plus size={16}/>Add product</Button>}>Confirm actual selling prices, stock and fitment information before enabling checkout.</SectionTitle><div className="toolbar"><div className="inline-search"><Search size={16}/><input aria-label="Search managed products" maxLength={150} placeholder="Name, brand or SKU" value={q} onChange={e=>{setQ(e.target.value);setPage(1);}}/></div><select aria-label="Product category" value={category} onChange={e=>{setCategory(e.target.value);setPage(1);}}><option value="">All categories</option>{categories.map(c=><option key={c}>{c}</option>)}</select><span className="muted small">{rows.length} products</span><Button variant="secondary small" disabled={!rows.length} onClick={()=>downloadCsv('products-'+stamp()+'.csv',toCsv(rows,productColumns))}><Download size={15}/>Export CSV</Button></div><div className="panel table-panel"><div className="table-scroll"><table><thead><tr><th>Product</th><th>Category</th><th>Price</th><th>Stock</th><th>State</th><th>Actions</th></tr></thead><tbody>{visible.map(p=><tr key={p.id}><td><div className="table-product"><ProductArt product={p}/><span><b>{p.name}</b><small>{p.sku} · {p.brand}</small></span></div></td><td>{p.category}</td><td>{money(p.price_cents)}<small>{p.price_confirmed?'Confirmed':'Reference only'}</small></td><td><Badge value={p.stock<10?'requested':'verified'}>{p.stock}</Badge></td><td><Badge value={p.active?'verified':'cancelled'}>{p.active?'Active':'Archived'}</Badge></td><td><div className="actions"><button className="button secondary small" aria-label={'Edit '+p.name} onClick={()=>setEditing(p)}><Edit3 size={17}/>Edit</button><button className="button secondary small" aria-label={'Archive '+p.name} onClick={()=>setArchive(p)}><Archive size={17}/>Archive</button></div></td></tr>)}</tbody></table></div>{!visible.length?<Empty title="No matching products">Try another search.</Empty>:null}<div className="pagination"><Button variant="secondary small" disabled={page<=1} onClick={()=>setPage(n=>n-1)}>Previous</Button><span>Page {page} of {Math.max(1,Math.ceil(rows.length/15))}</span><Button variant="secondary small" disabled={page*15>=rows.length} onClick={()=>setPage(n=>n+1)}>Next</Button></div></div><FormError error={task.error}/>{editing?<ProductEditor product={editing} onClose={()=>setEditing(null)}/>:null}{archive?<Confirm title="Archive this product?" danger onClose={()=>setArchive(null)} onConfirm={async()=>{const r=await task.perform(()=>repository.rpc('admin_archive_product',{p_product_id:archive.id}),'Product archived.');if(!r.ok)throw new Error('Could not archive product.');}}>The product will be removed from the public catalogue. Past orders and their recorded prices remain available.</Confirm>:null}</>;
}
function ProductEditor({product,onClose}){
 const{repository,data}=useApp(),task=useTask(),isNew=product.new,[values,setValues]=useState(isNew?{id:crypto.randomUUID(),sku:'',name:'',brand:'',category:'Engine Oil',description:'',price_cents:0,stock:0,image_url:'',fitment_note:'Confirm the vehicle application with the seller.',price_confirmed:false,active:true,specs:{}}:{...product,image_url:product.image_url||''}),[price,setPrice]=useState(isNew?'':(product.price_cents/100).toFixed(2)),[specs,setSpecs]=useState(Object.entries(product.specs||{}).map(([k,v])=>k+': '+v).join('\n')),[image,setImage]=useState(null),existingFitment=formatFitmentText((data.fitment||[]).filter(f=>f.product_id===product.id)),[fitmentText,setFitmentText]=useState(existingFitment);
 const update=(key,value)=>setValues({...values,[key]:value});
 return <Modal title={isNew?'Add product':'Edit product'} onClose={onClose} wide><form onSubmit={async e=>{e.preventDefault();const result=await task.perform(async()=>{const parsed={};for(const line of specs.split('\n').filter(l=>l.trim())){const idx=line.indexOf(':');if(idx<1||!line.slice(idx+1).trim())throw new Error('Use Name: Value for each specification.');const key=line.slice(0,idx).trim();if(['__proto__','constructor','prototype'].includes(key))throw new Error('Use another specification name.');parsed[key]=line.slice(idx+1).trim();}let imageUrl=values.image_url;if(image)imageUrl=await repository.upload(image,'product-images');const p=validate(productSchema,{...values,price_cents:cents(price),stock:Number(values.stock),image_url:imageUrl||'',specs:parsed});const fitment=parseFitmentText(fitmentText);if(fitment.errors.length)throw new Error(fitment.errors.join(' '));const saved=await repository.rpc('admin_save_product',{p_product:p,p_expected_version:isNew?null:product.version});if(fitmentText.trim()!==existingFitment.trim()){try{await repository.rpc('admin_set_fitment',{p_product_id:p.id,p_rows:fitment.rows});}catch(error){throw new Error('The product was saved, but its vehicle list was not. '+friendlyError(error));}}return saved;},'Product saved.');if(result.ok)onClose();}}><div className="form-grid">{[['name','Product name',180],['sku','SKU',80],['brand','Brand',80],['category','Category',80]].map(([key,text,max])=><Field key={key} label={text}><input required minLength={key==='brand'?1:2} maxLength={max} list={key==='category'?'categories':undefined} value={values[key]} onChange={e=>update(key,e.target.value)}/></Field>)}<datalist id="categories">{[...new Set(data.products.map(p=>p.category))].map(c=><option key={c}>{c}</option>)}</datalist><Field label="Selling price (RM)"><input type="number" required min="0.01" max="1000000" step="0.01" value={price} onChange={e=>setPrice(e.target.value)}/></Field><Field label="Actual units in stock"><input type="number" required min="0" max="1000000" step="1" value={values.stock} onChange={e=>update('stock',e.target.value)}/></Field><Field label="Description" className="full"><textarea required minLength={10} maxLength={4000} value={values.description} onChange={e=>update('description',e.target.value)}/></Field><Field label="Specifications (Name: Value, one per line)" className="full"><textarea maxLength={16000} value={specs} onChange={e=>setSpecs(e.target.value)}/></Field><Field label="Fitment note" className="full"><textarea required minLength={5} maxLength={1000} value={values.fitment_note} onChange={e=>update('fitment_note',e.target.value)}/></Field><Field label="Vehicles this product is listed for" className="full" hint="One per line: Make, Model, Years. Years are optional, for example Proton, X50, 2020-2024. Leave empty if you have no fitment information; customers are then told to ask."><textarea maxLength={4000} value={fitmentText} onChange={e=>setFitmentText(e.target.value)}/></Field><Field label="Upload a store-owned product photo" hint="JPG, PNG or WebP · maximum 5 MB"><input type="file" accept="image/jpeg,image/png,image/webp" onChange={e=>setImage(e.target.files[0]||null)}/></Field><Field label="Or use an authorised HTTPS image URL"><input type="url" maxLength={2000} value={values.image_url} onChange={e=>update('image_url',e.target.value)}/></Field><label className="checkbox full"><input type="checkbox" checked={values.price_confirmed} onChange={e=>update('price_confirmed',e.target.checked)}/>I confirm this is the store’s selling price, not just the supplier reference price.</label><label className="checkbox full"><input type="checkbox" checked={values.active} onChange={e=>update('active',e.target.checked)}/>Show in the public catalogue</label></div>{product.source_url?<p className="muted small">Reference: <a href={product.source_url} target="_blank" rel="noopener noreferrer">Supplier listing ↗</a> · Observed {product.source_observed_at}</p>:null}<FormError error={task.error}/><div className="actions"><Button busy={task.busy}>Save product</Button><Button variant="secondary" type="button" onClick={onClose}>Cancel</Button></div></form></Modal>;
}
function UsersPage(){const{data,repository,profile}=useApp(),task=useTask(),[q,setQ]=useState(''),[edit,setEdit]=useState(null),[remove,setRemove]=useState(null),[invite,setInvite]=useState(false),[page,setPage]=useState(1);const matches=data.users.filter(u=>(u.full_name+' '+u.email+' '+u.role).toLowerCase().includes(q.toLowerCase())),pages=Math.max(1,Math.ceil(matches.length/20)),safePage=Math.min(page,pages),rows=matches.slice((safePage-1)*20,safePage*20);return <><SectionTitle eyebrow="ACCESS & ACCOUNT MANAGEMENT" title="Users & roles" action={<Button onClick={()=>setInvite(true)}><Plus size={16}/>Invite user</Button>}>Customer registration never grants staff access. Role changes are checked in the database.</SectionTitle><div className="toolbar"><div className="inline-search"><Search size={16}/><input aria-label="Search users" maxLength={150} value={q} onChange={e=>{setQ(e.target.value);setPage(1);}} placeholder="Search name, email or role"/></div><span className="muted small">{matches.length} users</span></div><div className="panel table-panel"><div className="table-scroll"><table><thead><tr><th>User</th><th>Role</th><th>Customer type</th><th>State</th><th>Actions</th></tr></thead><tbody>{rows.map(u=><tr key={u.id}><td><b>{u.full_name}</b><small>{u.email}</small></td><td><Badge value="verified">{u.role}</Badge></td><td>{label(u.business_type)}</td><td><Badge value={u.is_active?'verified':'cancelled'}>{u.is_active?'Active':'Inactive'}</Badge></td><td><div className="actions"><Button variant="secondary small" onClick={()=>setEdit(u)}>Edit</Button><button className="icon-button" disabled={u.id===profile.id} aria-label={'Delete '+u.full_name} onClick={()=>setRemove(u)}><Trash2 size={17}/></button></div></td></tr>)}</tbody></table></div>{pages>1?<div className="pagination"><Button variant="secondary small" disabled={safePage<=1} onClick={()=>setPage(safePage-1)}>Previous</Button><span>Page {safePage} of {pages}</span><Button variant="secondary small" disabled={safePage>=pages} onClick={()=>setPage(safePage+1)}>Next</Button></div>:null}</div><FormError error={task.error}/>{edit?<UserEditor user={edit} onClose={()=>setEdit(null)}/>:null}{invite?<InviteUser onClose={()=>setInvite(false)}/>:null}{remove?<Confirm title="Delete this user account?" danger onClose={()=>setRemove(null)} onConfirm={async()=>{const r=await task.perform(()=>repository.deleteUser(remove.id),'User removed.');if(!r.ok)throw new Error('Deletion was not completed. Accounts with business history should be deactivated instead.');}}>Accounts with orders or historical activity may not be deleted. Use Edit → Inactive to remove access while retaining business records.</Confirm>:null}</>;}
function UserEditor({user,onClose}){const{repository}=useApp(),task=useTask(),[name,setName]=useState(user.full_name),[role,setRole]=useState(user.role),[active,setActive]=useState(user.is_active);return <Modal title="Edit user access" onClose={onClose}><form onSubmit={async e=>{e.preventDefault();const r=await task.perform(()=>repository.rpc('admin_update_profile',{p_user_id:user.id,p_name:name,p_role:role,p_active:active}),'User access updated.');if(r.ok)onClose();}}><p className="muted">{user.email}</p><Field label="Full name"><input required minLength={2} maxLength={100} value={name} onChange={e=>setName(e.target.value)}/></Field><Field label="Role"><select value={role} onChange={e=>setRole(e.target.value)}>{['customer','worker','admin'].map(r=><option key={r} value={r}>{label(r)}</option>)}</select></Field><label className="checkbox"><input type="checkbox" checked={active} onChange={e=>setActive(e.target.checked)}/>Active account</label><Notice>Workers manage operations. Only admins manage users, products, promotions and store settings. You cannot remove your own admin access.</Notice><FormError error={task.error}/><Button busy={task.busy}>Save user</Button></form></Modal>;}
function InviteUser({onClose}){const{repository,preview}=useApp(),task=useTask(),[name,setName]=useState(''),[email,setEmail]=useState(''),[role,setRole]=useState('worker');return <Modal title="Invite a user" onClose={onClose}><form onSubmit={async e=>{e.preventDefault();const r=await task.perform(()=>repository.inviteUser({name,email,role}),preview?'Preview user created; no email sent.':'User invitation created. Check email delivery in Supabase.');if(r.ok)onClose();}}><Field label="Full name"><input required minLength={2} maxLength={100} value={name} onChange={e=>setName(e.target.value)}/></Field><Field label="Email"><input type="email" required maxLength={254} value={email} onChange={e=>setEmail(e.target.value)}/></Field><Field label="Role"><select value={role} onChange={e=>setRole(e.target.value)}>{['customer','worker','admin'].map(r=><option key={r} value={r}>{label(r)}</option>)}</select></Field><p className="muted small">Live invitations require the Vercel server environment and Supabase email delivery to be configured. Never place the service-role key in browser code.</p><FormError error={task.error}/><Button busy={task.busy}>{preview?'Create preview user':'Send invitation'}</Button></form></Modal>;}
function AnnouncementsPage(){const{data,repository}=useApp(),task=useTask(),[edit,setEdit]=useState(null),[remove,setRemove]=useState(null);return <><SectionTitle eyebrow="KEEP SHOPPERS INFORMED" title="Announcements" action={<Button onClick={()=>setEdit({title:'',body:'',active:true})}><Plus size={16}/>New announcement</Button>}>Publish factual store updates. Public text is rendered safely, without executable HTML.</SectionTitle><div className="content-card-grid">{data.announcements.map(a=><article className="panel" key={a.id}><Badge value={a.active?'verified':'cancelled'}>{a.active?'Published':'Hidden'}</Badge><h3>{a.title}</h3><p>{a.body}</p><div className="actions"><Button variant="secondary small" onClick={()=>setEdit(a)}>Edit</Button><Button variant="secondary small" onClick={()=>setRemove(a)}>Delete</Button></div></article>)}</div>{!data.announcements.length?<Empty title="No announcements yet">Create a store update to show on the home page.</Empty>:null}{edit?<AnnouncementEditor announcement={edit} onClose={()=>setEdit(null)}/>:null}{remove?<Confirm title="Delete announcement?" onClose={()=>setRemove(null)} onConfirm={async()=>{const r=await task.perform(()=>repository.rpc('admin_delete_announcement',{p_id:remove.id}),'Announcement deleted.');if(!r.ok)throw new Error('Could not delete announcement.');}}>This removes the announcement from the storefront.</Confirm>:null}</>;}
function AnnouncementEditor({announcement:a,onClose}){const{repository}=useApp(),task=useTask(),[values,setValues]=useState(a);return <Modal title={a.id?'Edit announcement':'New announcement'} onClose={onClose}><form onSubmit={async e=>{e.preventDefault();const r=await task.perform(()=>{const v=validate(announcementSchema,values);return repository.rpc('admin_save_announcement',{p_id:a.id||null,p_title:v.title,p_body:v.body,p_active:v.active});},'Announcement saved.');if(r.ok)onClose();}}><Field label="Title"><input required minLength={3} maxLength={160} value={values.title} onChange={e=>setValues({...values,title:e.target.value})}/></Field><Field label="Message"><textarea required minLength={5} maxLength={3000} value={values.body} onChange={e=>setValues({...values,body:e.target.value})}/></Field><label className="checkbox"><input type="checkbox" checked={values.active} onChange={e=>setValues({...values,active:e.target.checked})}/>Publish on the store</label><FormError error={task.error}/><Button busy={task.busy}>Save announcement</Button></form></Modal>;}
function PromotionsPage(){const{data,repository}=useApp(),task=useTask(),[edit,setEdit]=useState(null),[remove,setRemove]=useState(null);return <><SectionTitle eyebrow="EXPLICIT PRICING, CONTROLLED OFFERS" title="Promotions" action={<Button onClick={()=>setEdit({new:true})}><Plus size={16}/>Add promotion</Button>}>One redemption per customer. Order creation validates dates, usage caps and minimum spend.</SectionTitle><div className="panel table-panel"><div className="table-scroll"><table><thead><tr><th>Code</th><th>Offer</th><th>Minimum</th><th>Usage</th><th>Ends</th><th>Actions</th></tr></thead><tbody>{data.promotions.map(p=><tr key={p.id}><td><b>{p.code}</b><small>{p.active?'Enabled':'Disabled'}</small></td><td>{p.kind==='percent'?p.value+'%':money(p.value)}</td><td>{money(p.minimum_cents)}</td><td>{p.used_count} / {p.maximum_uses}</td><td>{dateTime(p.ends_at)}</td><td><div className="actions"><Button variant="secondary small" onClick={()=>setEdit(p)}>Edit</Button><Button variant="secondary small" onClick={()=>setRemove(p)}>Remove</Button></div></td></tr>)}</tbody></table></div>{!data.promotions.length?<Empty title="No promotions yet">Create an offer only after checking your costs and margins.</Empty>:null}</div>{edit?<PromotionEditor promotion={edit} onClose={()=>setEdit(null)}/>:null}{remove?<Confirm title="Remove promotion?" onClose={()=>setRemove(null)} onConfirm={async()=>{const r=await task.perform(()=>repository.rpc('admin_delete_promotion',{p_id:remove.id}),'Promotion removed or archived.');if(!r.ok)throw new Error('Could not remove promotion.');}}>Unused promotions are deleted. Promotions referenced by orders are disabled so historical order records remain intact.</Confirm>:null}</>;}
function PromotionEditor({promotion:p,onClose}){const{repository}=useApp(),task=useTask(),dateInput=d=>new Date(new Date(d).getTime()-new Date(d).getTimezoneOffset()*60000).toISOString().slice(0,16),[values,setValues]=useState(p.new?{code:'',kind:'percent',amount:'10',minimum:'0',maximum_uses:100,starts_at:dateInput(new Date()),ends_at:dateInput(new Date(Date.now()+7*86400000)),active:true}:{...p,amount:p.kind==='percent'?String(p.value):(p.value/100).toFixed(2),minimum:(p.minimum_cents/100).toFixed(2),starts_at:dateInput(p.starts_at),ends_at:dateInput(p.ends_at)}),update=(k,v)=>setValues({...values,[k]:v});return <Modal title={p.new?'Create promotion':'Edit promotion'} onClose={onClose}><form onSubmit={async e=>{e.preventDefault();const r=await task.perform(()=>{const v=validate(promotionSchema,{code:values.code,kind:values.kind,value:values.kind==='percent'?Number(values.amount):cents(values.amount),minimum_cents:cents(values.minimum),maximum_uses:Number(values.maximum_uses),starts_at:new Date(values.starts_at).toISOString(),ends_at:new Date(values.ends_at).toISOString(),active:values.active});return repository.rpc('admin_save_promotion',{p_promotion:{...v,...(!p.new?{id:p.id}:{})}});},'Promotion saved.');if(r.ok)onClose();}}><div className="form-grid"><Field label="Code"><input required minLength={3} maxLength={30} pattern="[A-Z0-9_-]+" value={values.code} onChange={e=>update('code',e.target.value.toUpperCase())}/></Field><Field label="Discount type"><select value={values.kind} onChange={e=>update('kind',e.target.value)}><option value="percent">Percentage</option><option value="fixed">Fixed amount (RM)</option></select></Field><Field label={values.kind==='percent'?'Discount (%)':'Discount (RM)'}><input type="number" required min={values.kind==='percent'?1:.01} max={values.kind==='percent'?100:1000000} step={values.kind==='percent'?1:.01} value={values.amount} onChange={e=>update('amount',e.target.value)}/></Field><Field label="Minimum item subtotal (RM)"><input type="number" required min="0" step="0.01" value={values.minimum} onChange={e=>update('minimum',e.target.value)}/></Field><Field label="Maximum total redemptions"><input type="number" required min="1" max="1000000" value={values.maximum_uses} onChange={e=>update('maximum_uses',e.target.value)}/></Field><div/><Field label="Starts (your local time)"><input type="datetime-local" required value={values.starts_at} onChange={e=>update('starts_at',e.target.value)}/></Field><Field label="Ends (your local time)"><input type="datetime-local" required value={values.ends_at} onChange={e=>update('ends_at',e.target.value)}/></Field><label className="checkbox full"><input type="checkbox" checked={values.active} onChange={e=>update('active',e.target.checked)}/>Enable this offer within the selected dates</label></div><FormError error={task.error}/><Button busy={task.busy}>Save promotion</Button></form></Modal>;}
function RestockPage(){const{data,profile}=useApp(),[newRequest,setNewRequest]=useState(false),[resolve,setResolve]=useState(null);return <><SectionTitle eyebrow="INVENTORY COORDINATION" title="Restock requests" action={<Button onClick={()=>setNewRequest(true)}><Plus size={16}/>Request stock</Button>}>Workers can request stock. Only admins record physically received inventory.</SectionTitle><div className="panel table-panel"><div className="table-scroll"><table><thead><tr><th>Product</th><th>Requested</th><th>Reason</th><th>Status</th><th>Actions</th></tr></thead><tbody>{data.restock.map(r=><tr key={r.id}><td><b>{data.products.find(p=>p.id===r.product_id)?.name||r.product_id}</b><small>{dateTime(r.created_at)}</small></td><td>{r.quantity} units</td><td className="wrap-cell">{r.reason}{r.admin_note?<small>Admin: {r.admin_note}</small>:null}</td><td><Badge value={r.status}/></td><td>{profile.role==='admin'&&r.status!=='resolved'?<Button variant="secondary small" onClick={()=>setResolve(r)}>Record stock received</Button>:<span className="muted small">{r.status==='resolved'?'Completed':'Awaiting admin'}</span>}</td></tr>)}</tbody></table></div>{!data.restock.length?<Empty title="No restock requests">Use Request stock when an item needs replenishment.</Empty>:null}</div>{newRequest?<RestockForm onClose={()=>setNewRequest(false)}/>:null}{resolve?<RestockForm request={resolve} onClose={()=>setResolve(null)}/>:null}</>;}
function RestockForm({request,onClose}){const{data,repository}=useApp(),task=useTask(),[product,setProduct]=useState(request?.product_id||''),[quantity,setQuantity]=useState(request?.quantity||1),[note,setNote]=useState('');return <Modal title={request?'Record physically received stock':'Request restock'} onClose={onClose}><form onSubmit={async e=>{e.preventDefault();const r=await task.perform(()=>{if(!Number.isSafeInteger(Number(quantity))||Number(quantity)<1||Number(quantity)>1000000||note.trim().length<5)throw new Error('Enter a valid whole quantity and clear reason.');return request?repository.rpc('resolve_restock',{p_request_id:request.id,p_units_received:Number(quantity),p_note:note}):repository.rpc('request_restock',{p_product_id:product,p_quantity:Number(quantity),p_reason:note});},request?'Stock received and request resolved.':'Restock request sent to admins.');if(r.ok)onClose();}}><Field label="Product"><select required disabled={Boolean(request)} value={product} onChange={e=>setProduct(e.target.value)}><option value="">Choose a product</option>{data.products.map(p=><option key={p.id} value={p.id}>{p.sku} · {p.name} ({p.stock} in stock)</option>)}</select></Field><Field label={request?'Units actually received':'Units requested'}><input required type="number" min="1" max="1000000" step="1" value={quantity} onChange={e=>setQuantity(e.target.value)}/></Field><Field label={request?'Receiving note':'Reason'}><textarea required minLength={5} maxLength={1000} value={note} onChange={e=>setNote(e.target.value)}/></Field>{request?<label className="checkbox"><input required type="checkbox"/>I counted and physically received these units.</label>:null}<FormError error={task.error}/><Button busy={task.busy}>{request?'Add received units':'Send restock request'}</Button></form></Modal>;}
function RefundsPage(){const{data,profile,go}=useApp(),[review,setReview]=useState(null),[pay,setPay]=useState(null);return <><SectionTitle eyebrow="REVIEW FIRST, TRANSFER SEPARATELY" title="Returns & refunds">Full-order refund requests. Staff review eligibility; only admins record an actual refund transfer.</SectionTitle><div className="content-card-grid">{data.refunds.map(r=>{const o=data.orders.find(o=>o.id===r.order_id);return <article className="panel" key={r.id}><div className="panel-heading"><h3>{o?'GL-'+o.order_number:'Order '+r.order_id.slice(0,8)}</h3><Badge value={r.status}/></div><p>{r.reason}</p><dl className="bank-details"><div><dt>Requested amount</dt><dd>{money(r.amount_cents)}</dd></div><div><dt>Returned goods received</dt><dd>{r.return_received?'Confirmed':'Not confirmed'}</dd></div></dl>{r.staff_note?<Notice>{r.staff_note}</Notice>:null}{r.transfer_reference?<p className="small">Refund reference: {r.transfer_reference}</p>:null}<div className="actions"><Link className="button secondary small" to={'/workspace/orders/'+r.order_id} go={go}>View order</Link>{['requested','approved'].includes(r.status)?<Button variant="secondary small" onClick={()=>setReview(r)}>Review</Button>:null}{profile.role==='admin'&&r.status==='approved'?<Button variant="small" onClick={()=>setPay(r)}>Record refund transfer</Button>:null}</div></article>;})}</div>{!data.refunds.length?<Empty title="No refund requests">Customer requests will appear here for review.</Empty>:null}{review?<RefundReview refund={review} onClose={()=>setReview(null)}/>:null}{pay?<RefundPayment refund={pay} onClose={()=>setPay(null)}/>:null}</>;}
function RefundReview({refund,onClose}){const{repository}=useApp(),task=useTask(),[approved,setApproved]=useState(true),[returned,setReturned]=useState(refund.return_received),[note,setNote]=useState(refund.staff_note||'');return <Modal title="Review refund request" onClose={onClose}><p>{refund.reason}</p><form onSubmit={async e=>{e.preventDefault();const r=await task.perform(()=>repository.rpc('review_refund',{p_refund_id:refund.id,p_approved:approved,p_note:note,p_return_received:returned}),'Refund review saved.');if(r.ok)onClose();}}><Field label="Decision"><select value={approved?'yes':'no'} onChange={e=>setApproved(e.target.value==='yes')}><option value="yes">Approve for processing</option><option value="no">Decline request</option></select></Field><Field label="Note for the customer"><textarea required minLength={5} maxLength={1000} value={note} onChange={e=>setNote(e.target.value)}/></Field><label className="checkbox"><input type="checkbox" checked={returned} onChange={e=>setReturned(e.target.checked)}/>Returned goods have physically arrived</label><Notice>Approval does not move money. An admin must separately record the completed transfer.</Notice><FormError error={task.error}/><Button busy={task.busy}>Save review</Button></form></Modal>;}
function RefundPayment({refund,onClose}){const{repository}=useApp(),task=useTask(),[reference,setReference]=useState(''),[restock,setRestock]=useState(false);return <Modal title="Record completed refund transfer" onClose={onClose}><p>Refund amount: <b>{money(refund.amount_cents)}</b>. Make the actual transfer outside the website, verify it, then record its reference.</p><form onSubmit={async e=>{e.preventDefault();const r=await task.perform(()=>repository.rpc('confirm_refund',{p_refund_id:refund.id,p_reference:reference,p_restock:restock}),'Refund transfer recorded.');if(r.ok)onClose();}}><Field label="Bank refund transfer reference"><input required minLength={5} maxLength={100} value={reference} onChange={e=>setReference(e.target.value)}/></Field><label className="checkbox"><input type="checkbox" disabled={!refund.return_received} checked={restock} onChange={e=>setRestock(e.target.checked)}/>Restock the physically returned items</label><label className="checkbox"><input type="checkbox" required/>I completed and verified the actual refund transfer.</label><FormError error={task.error}/><Button busy={task.busy}>Record paid refund</Button></form></Modal>;}
function FeedbackPage(){const{data,profile,repository}=useApp(),task=useTask(),[reply,setReply]=useState(null),[body,setBody]=useState(''),[moderate,setModerate]=useState(null),[reason,setReason]=useState('');return <><SectionTitle eyebrow="VERIFIED PURCHASE FEEDBACK" title="Customer feedback">Buyers can review only after confirming receipt. Replies are shown with the public review.</SectionTitle><div className="reviews-list">{data.reviews.map(r=><article key={r.id}><div className="review-top"><b>{r.display_name}</b><Stars value={r.rating} size={15}/><Badge value={r.published?'verified':'cancelled'}>{r.published?'Published':'Hidden'}</Badge></div><small>{data.products.find(p=>p.id===r.product_id)?.name||r.product_id}</small>{parseReview(r.body).tags.length?<div className="review-tags">{parseReview(r.body).tags.map(t=><span key={t}>{t}</span>)}</div>:null}<p>{parseReview(r.body).text}</p>{r.reply?<div className="seller-reply"><b>Store reply</b><p>{r.reply}</p></div>:null}<div className="actions"><Button variant="secondary small" onClick={()=>{setReply(r);setBody(r.reply||'');}}>Respond</Button>{profile.role==='admin'?<Button variant="secondary small" onClick={()=>{setModerate(r);setReason('');}}>{r.published?'Hide with reason':'Restore review'}</Button>:null}</div></article>)}</div>{!data.reviews.length?<Empty title="No verified reviews yet">Reviews appear after a buyer receives and reviews a purchased product.</Empty>:null}{reply?<Modal title="Reply to customer feedback" onClose={()=>setReply(null)}><p>{reply.body}</p><form onSubmit={async e=>{e.preventDefault();const r=await task.perform(()=>repository.rpc('reply_review',{p_review_id:reply.id,p_reply:body}),'Reply saved.');if(r.ok)setReply(null);}}><Field label="Public seller response"><textarea required minLength={2} maxLength={2000} value={body} onChange={e=>setBody(e.target.value)}/></Field><FormError error={task.error}/><Button busy={task.busy}>Publish response</Button></form></Modal>:null}{moderate?<Modal title="Moderate review" onClose={()=>setModerate(null)}><p>Record a reason. Moderation changes visibility; it does not erase the purchase or review record.</p><form onSubmit={async e=>{e.preventDefault();const r=await task.perform(()=>repository.rpc('moderate_review',{p_review_id:moderate.id,p_published:!moderate.published,p_reason:reason}),'Review visibility updated.');if(r.ok)setModerate(null);}}><Field label="Moderation reason"><textarea required minLength={5} maxLength={1000} value={reason} onChange={e=>setReason(e.target.value)}/></Field><FormError error={task.error}/><Button busy={task.busy}>Save moderation</Button></form></Modal>:null}</>;}
function SettingsPage(){const{data,repository}=useApp(),task=useTask(),[v,setV]=useState(data.settings),[shipping,setShipping]=useState((data.settings.shipping_cents/100).toFixed(2)),[free,setFree]=useState((data.settings.free_shipping_cents/100).toFixed(2)),update=(k,value)=>setV({...v,[k]:value});return <><SectionTitle eyebrow="BEFORE YOU ACCEPT REAL ORDERS" title="Store settings">Confirm business bank details, selling prices, inventory and policies before enabling checkout.</SectionTitle><form className="panel settings-form" onSubmit={async e=>{e.preventDefault();await task.perform(()=>{if(v.checkout_enabled&&(!v.bank_name.trim()||!v.bank_account_name.trim()||!/^[0-9 -]{6,30}$/.test(v.bank_account_number)))throw new Error('Enter valid business bank details before enabling checkout.');return repository.rpc('admin_save_settings',{p_settings:{...v,shipping_cents:cents(shipping),free_shipping_cents:cents(free)}});},'Store settings saved.');}}><fieldset className="settings-section"><legend>Store profile<span>How customers see and contact the store.</span></legend><div className="form-grid">{[['store_name','Store name',100],['contact_email','Contact email',254]].map(([key,name,max])=><Field key={key} label={name}><input type={key==='contact_email'?'email':'text'} required={key==='store_name'} maxLength={max} value={v[key]} onChange={e=>update(key,e.target.value)}/></Field>)}</div></fieldset><fieldset className="settings-section"><legend>Bank transfer details<span>Copied onto a customer's order when they place it. Signed-out visitors and other customers cannot read them.</span></legend><div className="form-grid">{[['bank_name','Business bank',100],['bank_account_name','Bank account name',120],['bank_account_number','Bank account number',30]].map(([key,name,max])=><Field key={key} label={name}><input type="text" required={v.checkout_enabled} maxLength={max} value={v[key]} onChange={e=>update(key,e.target.value)}/></Field>)}</div></fieldset><fieldset className="settings-section"><legend>Delivery<span>One configured charge for every order. Live carrier quotations are not part of this release.</span></legend><div className="form-grid"><Field label="Configured delivery charge (RM)"><input required min="0" max="1000" step="0.01" type="number" value={shipping} onChange={e=>setShipping(e.target.value)}/></Field><Field label="Free-delivery threshold (RM; 0 disables)"><input required min="0" max="1000000" step="0.01" type="number" value={free} onChange={e=>setFree(e.target.value)}/></Field></div></fieldset><fieldset className="settings-section"><legend>Invoices<span>Shown on the PDF invoice a customer downloads for a paid order.</span></legend><Field label="Seller details on invoices" hint="Company legal name, address and registration or SST number, exactly as they should appear."><textarea maxLength={1000} placeholder="GearLane Sdn Bhd (Reg. 202001234567)&#10;1 Jalan Demo, 50000 Kuala Lumpur" value={v.invoice_details||''} onChange={e=>update('invoice_details',e.target.value)}/></Field>{!(v.invoice_details||'').trim()?<Notice>Invoices currently show only the store name. Add your company details if your invoices must show them.</Notice>:null}</fieldset><fieldset className="settings-section"><legend>Returns<span>Shown on product pages and in the shopping guide.</span></legend><Field label="Return policy / eligibility"><textarea maxLength={4000} value={v.return_policy} onChange={e=>update('return_policy',e.target.value)}/></Field></fieldset><fieldset className="settings-section checkout-switch"><legend>Checkout<span>Customers can only place orders while this is on.</span></legend><label className="checkbox"><input type="checkbox" checked={v.checkout_enabled} onChange={e=>update('checkout_enabled',e.target.checked)}/>Enable checkout with these bank and delivery settings</label></fieldset><Notice>Research catalogue items start with zero inventory and unconfirmed prices. Confirm each actual selling price and stock in Products. This release uses one configured delivery charge, not live carrier quotations.</Notice><FormError error={task.error}/><Button busy={task.busy}>Save store settings</Button></form></>;}
function AuditPage(){const{data}=useApp();return <><SectionTitle eyebrow="ADMINISTRATIVE TRACEABILITY" title="Activity log">Latest 100 database audit entries. Business records retain their original order prices.</SectionTitle><div className="panel table-panel"><div className="table-scroll"><table><thead><tr><th>Time</th><th>Action</th><th>Actor</th><th>Target</th></tr></thead><tbody>{data.audit.map(e=><tr key={e.id}><td>{dateTime(e.created_at)}</td><td>{label(e.action)}</td><td>{data.users.find(u=>u.id===e.actor_id)?.full_name||e.actor_id||'System'}</td><td className="wrap-cell">{e.target}</td></tr>)}</tbody></table></div>{!data.audit.length?<Empty title="No audit entries yet">Administrative changes and payment/refund actions will appear here.</Empty>:null}</div></>;}
